 const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a,pick=a=>a[rnd(0,a.length-1)],shuffle=a=>{a=[...a];for(let i=a.length-1;i;i--){const j=rnd(0,i);[a[i],a[j]]=[a[j],a[i]]}return a},round=x=>Math.round((x+Number.EPSILON)*100)/100,fmt=x=>String(round(x)).replace('.',',').replace(/-/g,'−'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
