 models.fixedCode=(l,v)=>{const symbols=pick(['ABAC','CAB','DDAB','BCDAA','ABCDAB']),map={A:'00',B:'01',C:'10',D:'11'},target=v%2;return number(`Таблица кода: A → 00; B → 01; C → 10; D → 11. Для сообщения ${target?symbols.split('').map(x=>map[x]).join(' '):symbols} найдите ${target?'количество исходных букв':'длину двоичной записи в битах'}.`,target?symbols.length:symbols.length*2,'','Каждой букве сопоставлены два бита. При декодировании каждую пару битов заменяют одной буквой.','I = число букв · 2 бита',[`Исходное слово: ${symbols}.`,`Его код: ${symbols.split('').map(x=>map[x]).join(' ')}.`],{kind:'fixed-code',symbols,target})};
 models.pixels=(l,v)=>{const w=rnd(4,12)*10,h=rnd(3,10)*10,target=v%2;return number(target?`Растровый рисунок имеет ширину ${w} пикселей и содержит ${w*h} пикселей. Какова высота?`:`Растровый рисунок имеет ширину ${w} и высоту ${h} пикселей. Сколько всего пикселей?`,target?h:w*h,target?'пикселей':'пикселей','В прямоугольном растре число пикселей равно произведению ширины на высоту.','N = ширина · высота',[target?`${w*h}/${w}.`:`${w} · ${h}.`],{kind:'pixels',w,h,target})};
