 models.robotDistance=(l,v)=>{const steps=rnd(3,12),length=pick([5,10,15,20]),back=l===3?rnd(1,2):0;return number(`Робот движется по одной прямой: ${steps} шагов вперёд${back?`, затем ${back} шага назад`:''}. Один шаг ${length} см. На каком расстоянии от старта он окажется?`,(steps-back)*length,'см','На одной прямой шаги в противоположных направлениях вычитаются. Затем число оставшихся шагов умножают на длину шага.','s = (шаги вперёд − шаги назад) · длина шага',[`(${steps} − ${back}) · ${length}.`],{kind:'robot-distance',steps,length,back})};
 models.bytes=(l,v)=>{const count=pick([2,4,8,16,32,64]),target=v%3;if(target===0)return number(`Объём сообщения ${count} байт. Сколько это бит? В задаче 1 байт = 8 бит.`,count*8,'бит','Для перевода байтов в биты умножают на 8.','Iбит = Iбайт · 8',[`${count} · 8.`],{kind:'multiply',a:count,b:8});if(target===1)return number(`Файл занимает ${count} КиБ. Сколько это байт? 1 КиБ = 1024 байта.`,count*1024,'байт','КиБ — двоичная единица объёма; один кибибайт содержит 1024 байта.','Iбайт = IКиБ · 1024',[`${count} · 1024.`],{kind:'multiply',a:count,b:1024});return number(`Папка содержит ${count} одинаковых файлов по ${l===3?3:1} МиБ. Каков общий объём в КиБ? 1 МиБ = 1024 КиБ.`,count*(l===3?3:1)*1024,'КиБ','Сначала сложите объёмы файлов, затем переведите МиБ в КиБ.','I = число файлов · объём файла · 1024',[`${count} · ${l===3?3:1} · 1024.`],{kind:'multiply',a:count*(l===3?3:1),b:1024})};
 models.fileSize=(l,v)=>{const pages=rnd(2,8),lines=pick([10,20,25]),chars=pick([20,30,40]),bytesPerChar=pick([1,2]),target=v%2,n=pages*lines*chars;return number(target?`В условном файле ${n} символов. Каждый символ занимает ровно ${bytesPerChar} байт. Найдите объём файла в битах. Служебные данные не учитываются.`:`Условный документ: ${pages} страниц, по ${lines} строк на странице, по ${chars} символов в строке. Каждый символ занимает ровно ${bytesPerChar} байт. Найдите объём в байтах без служебных данных.`,target?n*bytesPerChar*8:n*bytesPerChar,target?'бит':'байт','Количество символов умножают на число байтов на символ. Условие о постоянном числе байтов задано только для этой модели кодирования.','Iбайт = N · b; Iбит = N · b · 8',[`Всего символов ${n}.`,target?`${n} · ${bytesPerChar} · 8.`:`${n} · ${bytesPerChar}.`],{kind:'file-size',n,bytesPerChar,target})};
 models.transfer=(l,v)=>{const size=pick([2,4,8,12,16]),speed=pick([1,2,4,8]),target=v%2;return number(target?`За ${size*8/speed} с передано ${size} МБ данных. Найдите скорость в Мбит/с. В задаче 1 МБ = 1 000 000 байт, 1 Мбит = 1 000 000 бит; накладные расходы отсутствуют.`:`Файл ${size} МБ передаётся со скоростью ${speed} Мбит/с. Сколько секунд займёт передача? Здесь 1 МБ = 1 000 000 байт, 1 Мбит = 1 000 000 бит. Накладные расходы не учитываются.`,target?speed:size*8/speed,target?'Мбит/с':'с','Сначала согласуйте биты и байты. При одинаковых десятичных приставках один мегабайт содержит восемь мегабит.','t = I/v; v = I/t',[`${size} МБ = ${size*8} Мбит.`,target?`${size*8}/${size*8/speed}.`:`${size*8}/${speed}.`],{kind:'transfer',size,speed,target})};
 models.linear=(l,v)=>{const a=rnd(2,12),b=rnd(2,6),d=rnd(1,7);let code,value,steps;if(l===1){code=`a = ${a}\nb = ${b}\nprint(a + b * ${d})`;value=a+b*d;steps=[`Сначала ${b} · ${d} = ${b*d}.`,`Затем ${a} + ${b*d} = ${value}.`]}else if(l===2){code=`x = ${a}\nx = x + ${b}\nx = x * ${d}\nprint(x)`;value=(a+b)*d;steps=[`После прибавления x = ${a+b}.`,`После умножения x = ${value}.`]}else{code=`a = ${a}\nb = a + ${b}\na = b * ${d}\nprint(a - b)`;value=(a+b)*d-(a+b);steps=[`b = ${a+b}.`,`Новое a = ${a+b} · ${d} = ${(a+b)*d}.`,`Вывод: ${(a+b)*d} − ${a+b}.`]}return trace(code,value,'Присваивание меняет значение переменной. Умножение выполняется раньше сложения; команды выполняются сверху вниз.',steps)};
 models.branch=(l,v)=>{const x=rnd(-5,12),a=rnd(2,8),b=rnd(2,6),limit=rnd(0,6);let code,value,steps;if(l===1){const ok=x>limit;code=`x = ${x}\nif x > ${limit}:\n    y = x + ${a}\nelse:\n    y = x - ${b}\nprint(y)`;value=ok?x+a:x-b;steps=[`${x} > ${limit}: ${ok?'True':'False'}.`,`Выполняется ${ok?'первая':'вторая'} ветвь: y = ${value}.`]}else if(l===2){const ok=x>=limit&&x<limit+a;code=`x = ${x}\nif x >= ${limit} and x < ${limit+a}:\n    y = ${a}\nelse:\n    y = ${b}\nprint(y)`;value=ok?a:b;steps=[`Первое условие ${x>=limit}, второе ${x<limit+a}.`,`and истинно, только если истинны оба; y = ${value}.`]}else{code=`x = ${x}\nif x < 0:\n    y = ${a}\nelse:\n    if x < ${limit+a}:\n        y = ${b}\n    else:\n        y = ${a+b}\nprint(y)`;value=x<0?a:x<limit+a?b:a+b;steps=[`Сначала проверяется x < 0.`,`Если x неотрицателен, проверяется x < ${limit+a}.`,`Выбранное значение y = ${value}.`]}return trace(code,value,'Условный оператор выполняет только выбранную ветвь. Вложенное условие проверяется, только когда до него дошло выполнение.',steps)};
 models.fileRead=(l,v)=>{const values=Array.from({length:l+2},()=>rnd(1,20)),target=v%3,text=values.join('\n')+'\n';let code,value,steps;if(target===0){code='with open("data.txt", encoding="utf-8") as f:\n    x = int(f.readline())\nprint(x)';value=values[0];steps=['readline() читает первую строку.',`int преобразует её в число ${value}.`]}else if(target===1){code='with open("data.txt", encoding="utf-8") as f:\n    f.readline()\n    x = int(f.readline())\nprint(x)';value=values[1];steps=['Первая прочитанная строка пропускается.',`В x попадает второе число: ${value}.`]}else{code='with open("data.txt", encoding="utf-8") as f:\n    a = int(f.readline())\n    b = int(f.readline())\nprint(a + b)';value=values[0]+values[1];steps=[`a = ${values[0]}, b = ${values[1]}.`,`Их сумма ${value}.`]}const q=trace(code,value,'readline() читает следующую строку файла. Для арифметики текстовую строку преобразуют в число.',steps);q.prompt='Файл data.txt содержит по одному числу в строке: '+values.join('; ')+'. '+q.prompt;q.audit.files={'data.txt':text};return q};
 models.forLoop=(l,v)=>{const n=rnd(3,8),a=rnd(1,4);let code,value,steps;if(l===1){code=`s = 0\nfor i in range(${n}):\n    s = s + ${a}\nprint(s)`;value=n*a;steps=[`range(${n}) даёт ${n} итераций.`,`Каждый раз добавляется ${a}: результат ${value}.`]}else if(l===2){code=`s = 0\nfor i in range(1, ${n+1}):\n    s = s + i\nprint(s)`;value=n*(n+1)/2;steps=[`i принимает значения от 1 до ${n}.`,`Сумма: ${Array.from({length:n},(_,i)=>i+1).join(' + ')} = ${value}.`]}else{code=`s = 0\nfor i in range(${n}):\n    if i % 2 == 0:\n        s = s + i\nprint(s)`;value=Array.from({length:n},(_,i)=>i).filter(x=>x%2===0).reduce((x,y)=>x+y,0);steps=[`Из 0…${n-1} добавляются только чётные i.`,`Итоговая сумма ${value}.`]}return trace(code,value,'В range правая граница не включается. Проверяйте значения счётчика и обновление накопителя на каждой итерации.',steps)};
 models.whileLoop=(l,v)=>{const start=rnd(1,4),step=rnd(1,3),iterations=rnd(3,l===3?7:5),limit=start+step*(iterations-1);const code=`x = ${start}\nk = 0\nwhile x <= ${limit}:\n    x = x + ${step}\n    k = k + 1\nprint(${v%2?'x':'k'})`,value=v%2?start+step*iterations:iterations;return trace(code,value,'while проверяет условие перед каждой итерацией. После последнего увеличения x условие станет ложным.',[`Значения x при входе в тело: ${Array.from({length:iterations},(_,i)=>start+step*i).join(', ')}.`,`Выполнено ${iterations} итераций; итоговое x = ${start+step*iterations}.`])};
