 models.functionCall=(l,v)=>{const a=rnd(1,5),b=rnd(1,6),x=rnd(1,6);let code,value,steps;if(l===1){code=`def f(x):\n    return x * ${a} + ${b}\n\nprint(f(${x}))`;value=x*a+b;steps=[`Подставляем x = ${x}.`,`${x} · ${a} + ${b} = ${value}.`]}else if(l===2){code=`def f(x):\n    return x * ${a} + ${b}\n\nprint(f(f(${x})))`;const inner=x*a+b;value=inner*a+b;steps=[`Внутренний вызов f(${x}) = ${inner}.`,`Внешний вызов f(${inner}) = ${value}.`]}else{code=`def f(x):\n    if x % 2 == 0:\n        return x // 2\n    return x + ${b}\n\nprint(f(${x}) + f(${x+1}))`;const f=n=>n%2===0?n/2:n+b;value=f(x)+f(x+1);steps=[`f(${x}) = ${f(x)}.`,`f(${x+1}) = ${f(x+1)}.`,`Сумма ${value}.`]}return trace(code,value,'return возвращает результат вызова. У каждого вызова функции своё значение параметра.',steps)};
