 models.gamePosition=(l,v)=>{const x=rnd(10,50),dx=rnd(2,6),frames=rnd(3,8),back=l===3?rnd(1,2):0;return number(`В учебной 2D-игре координата x персонажа равна ${x} пикселям. За каждый из ${frames} кадров она увеличивается на ${dx}${back?`, а затем за ${back} кадра уменьшается на ${dx}`:''}. Чему равно итоговое x?`,x+(frames-back)*dx,'пикселей','Если скорость задана в пикселях за кадр, изменение координаты равно числу кадров, умноженному на это смещение.','x₂ = x₁ + число кадров · dx',[`${x} + (${frames} − ${back}) · ${dx}.`],{kind:'game-position',x,dx,frames,back})};
 models.binaryConversion=(l,v)=>{const base=pick(l===1?[2]:[2,8,16]),n=rnd(5,l===3?255:63),digits=n.toString(base).toUpperCase();return number(`Число ${digits} записано в системе с основанием ${base}. Переведите его в десятичную систему.`,n,'','Значение разряда равно цифре, умноженной на основание в степени позиции справа, начиная с нуля.','N = Σ(цифра · основание^позиция)',[digits.split('').map((d,i)=>`${parseInt(d,base)} · ${base}^${digits.length-1-i}`).join(' + ')+` = ${n}.`],{kind:'base-conversion',base,digits})};
 models.boolean=(l,v)=>{const a=rnd(0,1),b=rnd(0,1),d=rnd(0,1),expr=l===1?(v%2?'A OR B':'A AND B'):l===2?'NOT A AND B':'(A OR B) AND NOT C',value=l===1?(v%2?(a||b):(a&&b)):l===2?(!a&&!!b):((!!a||!!b)&&!d);return number(`A = ${a}, B = ${b}${l===3?', C = '+d:''}. Найдите значение ${expr}. Истина = 1, ложь = 0. NOT — отрицание, AND — И, OR — ИЛИ.`,Number(value),'','Сначала выполняется отрицание NOT, затем AND, затем OR; скобки меняют порядок.','NOT: меняет 0↔1; AND: обе истины; OR: хотя бы одна истина',[`Подставляем значения в ${expr}.`,`Результат: ${Number(value)}.`],{kind:'boolean',a,b,d,expr})};
 models.truthRows=(l,v)=>{const n=rnd(2,l===3?5:3);return number(`В логическом выражении ${n} независимых переменных, каждая принимает 0 или 1. Сколько строк содержит полная таблица истинности без заголовка?`,2**n,'строк','Каждая новая двоичная переменная удваивает число комбинаций значений.','N = 2ⁿ',[`2^${n} = ${2**n}.`],{kind:'power-two',n})};
 models.imageVolume=(l,v)=>{const w=pick([16,32,64]),h=pick([16,32,64]),depth=pick(l===1?[1,8]:[8,16,24]),bytes=w*h*depth/8;return number(`Растр ${w} × ${h} пикселей. На пиксель приходится ровно ${depth} бит. Сколько байтов занимает массив пикселей? Сжатия, заголовка и палитры в файле нет. 1 байт = 8 бит.`,bytes,'байт','Сначала найдите число пикселей, умножьте на глубину цвета, затем переведите биты в байты.','Iбайт = ширина · высота · глубина/8',[`${w} · ${h} · ${depth}/8 = ${bytes}.`],{kind:'image-volume',w,h,depth})};
 models.tableFormula=(l,v)=>{const a=rnd(2,15),b=rnd(2,12),d=rnd(1,8),formula=l===1?'=A1+B1':l===2?'=A1+B1*C1':'=(A1+B1)*C1',value=l===1?a+b:l===2?a+b*d:(a+b)*d;return number(`В электронной таблице A1 = ${a}, B1 = ${b}, C1 = ${d}. Какое число даст формула ${formula}?`,value,'','Формула использует значения ячеек. Скобки выполняются первыми, затем умножение, затем сложение.','Подставьте числа вместо адресов ячеек.',[l===1?`${a} + ${b}.`:l===2?`${a} + ${b} · ${d}.`:`(${a} + ${b}) · ${d}.`],{kind:'table-formula',a,b,d,l})};
 models.tableStats=(l,v)=>{const values=Array.from({length:l+3},()=>rnd(2,20)),target=v%4,value=target===0?values.reduce((a,b)=>a+b,0):target===1?Math.min(...values):target===2?Math.max(...values):values.reduce((a,b)=>a+b,0)/values.length,names=['сумму','минимальное значение','максимальное значение','среднее арифметическое'];return number(`Ячейки A1:A${values.length} содержат числа ${values.join('; ')}. Найдите ${names[target]} диапазона.`,value,'','Учитывайте все ячейки указанного диапазона; среднее арифметическое — сумма, делённая на количество чисел.','SUM — сумма; MIN — минимум; MAX — максимум; AVERAGE — среднее.',[target===0?values.join(' + ')+'.':target===1?`Наименьшее число ${value}.`:target===2?`Наибольшее число ${value}.`:`(${values.join(' + ')})/${values.length}.`],{kind:'table-stats',values,target})};
 models.filterCount=(l,v)=>{const values=Array.from({length:6},()=>rnd(2,20)),low=rnd(3,10),high=low+rnd(3,8),between=l>1,found=values.filter(x=>x>=low&&(!between||x<=high));return number(`Поле «Баллы» содержит записи ${values.join('; ')}. Фильтр оставляет баллы не меньше ${low}${between?' и не больше '+high:''}. Сколько записей будет видно?`,found.length,'записей','Фильтрация показывает только строки, удовлетворяющие условию. Исходные строки при этом не удаляются.',between?'low ≤ баллы ≤ high':'баллы ≥ low',[`Подходят значения: ${found.join(', ')||'нет таких значений'}.`,`Количество ${found.length}.`],{kind:'filter-count',values,low,high,between})};
 models.sqlQuery=(l,v)=>{const scores=Array.from({length:5},()=>rnd(2,20)),limit=rnd(5,15),target=v%3,query=target===0?`SELECT COUNT(*) FROM Results WHERE score >= ${limit};`:target===1?'SELECT MAX(score) FROM Results;':`SELECT SUM(score) FROM Results WHERE score >= ${Math.min(...scores)};`,value=target===0?scores.filter(x=>x>=limit).length:target===1?Math.max(...scores):scores.reduce((a,b)=>a+b,0);return number(`Таблица Results: поле score содержит ${scores.join('; ')}. Какое число вернёт запрос SQL?`+codeBlock(query),value,'','WHERE отбирает строки до вычисления агрегата. COUNT(*) считает строки; MAX находит максимум; SUM складывает значения.','SELECT агрегат FROM таблица WHERE условие;',[target===0?`Оставляем баллы ≥ ${limit}: ${scores.filter(x=>x>=limit).join(', ')||'ни одной строки'}.`:target===1?`Максимум равен ${value}.`:`Все данные проходят условие; сумма ${scores.join(' + ')}.`],{kind:'sql',scores,query})};
 models.graph=(l,v)=>{const ab=rnd(2,8),bc=rnd(2,8),ac=ab+bc+pick([-2,2,4]),bd=rnd(2,8),cd=rnd(2,8),paths=[ab+bd,ac+cd,ab+bc+cd,ac+bc+bd],value=Math.min(...paths);return number(`Неориентированный граф: A–B = ${ab}, B–C = ${bc}, A–C = ${ac}, B–D = ${bd}, C–D = ${cd}. Других рёбер нет. Найдите длину кратчайшего пути из A в D.`,value,'','При положительных весах кратчайший путь не содержит циклов. Сравните все простые пути от A до D.','Длина пути = сумма весов его рёбер.',[`A–B–D: ${ab+bd}.`,`A–C–D: ${ac+cd}.`,`A–B–C–D: ${ab+bc+cd}.`,`A–C–B–D: ${ac+bc+bd}.`,`Минимум ${value}.`],{kind:'graph',edges:[['A','B',ab],['B','C',bc],['A','C',ac],['B','D',bd],['C','D',cd]]})};
 models.neuron=(l,v)=>{const x=rnd(0,3),y=rnd(0,3),w1=rnd(1,3),w2=rnd(1,3),bias=rnd(-3,1),threshold=rnd(1,5),sum=w1*x+w2*y+bias,target=v%2;return number(`Учебный нейрон: z = ${w1}·x + ${w2}·y + (${bias}), x = ${x}, y = ${y}. ${target?`Выход равен 1 при z ≥ ${threshold}, иначе 0. Найдите выход.`:'Найдите z до применения функции активации.'}`,target?Number(sum>=threshold):sum,'','Сначала вычисляют взвешенную сумму со смещением, затем применяют явно заданное правило активации. Это упрощённая модель.','z = w₁x + w₂y + b',[`z = ${w1} · ${x} + ${w2} · ${y} + (${bias}) = ${sum}.`,...(target?[`${sum} ≥ ${threshold}: ${sum>=threshold}.`]:[])],{kind:'neuron',x,y,w1,w2,bias,threshold,target})};
 models.accuracy=(l,v)=>{const total=pick([20,40,50,100]),correct=total-pick([2,4,6,8,10]);return number(`На отдельной тестовой выборке из ${total} объектов классификатор дал ${correct} правильных ответов. Найдите долю правильных ответов в процентах.`,correct/total*100,'%','Accuracy — доля верных предсказаний среди всех проверенных объектов. Она не описывает все свойства модели и может вводить в заблуждение при дисбалансе классов.','accuracy = число верных/число всех · 100%',[`${correct}/${total} · 100%.`],{kind:'accuracy',total,correct})};
 models.sensor=(l,v)=>{const values=Array.from({length:5},()=>rnd(15,30)),threshold=rnd(20,25),greater=v%2===0,count=values.filter(x=>greater?x>threshold:x>=threshold).length;return number(`Учебный датчик прислал значения ${values.join('; ')}. Контроллер посылает одно уведомление на каждое значение ${greater?'строго больше':'не меньше'} ${threshold}. Сколько уведомлений?`,count,'','Не путайте строгое сравнение > с нестрогим ≥. Каждое измерение проверяется отдельно.','Количество = число значений, проходящих условие.',[`Подходят ${values.filter(x=>greater?x>threshold:x>=threshold).join(', ')||'ни одно значение'}.`],{kind:'sensor',values,threshold,greater})};
 models.storage=(l,v)=>{const free=pick([32,64,128,256]),size=pick([3,5,6,10]),count=Math.floor(free/size);return number(`На учебном устройстве свободно ${free} МиБ. Один файл занимает ${size} МиБ. Сколько целых таких файлов поместится без удаления других данных? Служебный объём не учитывается.`,count,'файлов','Поместится только целое число файлов: дробную часть результата деления отбрасывают.','N = целая часть (свободный объём/размер файла)',[`${free}/${size} ≈ ${fmt(free/size)}; целых файлов ${count}.`],{kind:'storage',free,size})};
 models.alphabetVolume=(l,v)=>{const bits=rnd(2,6),alphabet=2**bits,length=rnd(5,20),target=l===1?0:v%2+1,value=target===0?bits:target===1?bits*length:length;return number(target===0?`Равномерный двоичный код использует все комбинации одной длины для алфавита из ${alphabet} символов. Сколько бит приходится на символ?`:target===1?`Алфавит из ${alphabet} символов кодируется равномерным двоичным кодом минимальной длины. В сообщении ${length} символов. Найдите его объём в битах без служебных данных.`:`Алфавит из ${alphabet} символов кодируется равномерным двоичным кодом минимальной длины. Сообщение занимает ${bits*length} бит без служебных данных. Сколько в нём символов?`,value,target===0?'бит/символ':target===1?'бит':'символов','Для алфавита из N = 2ⁱ символов минимальный равномерный код имеет i бит на символ.','N = 2ⁱ; I = K · i',[`${alphabet} = 2^${bits}, значит i = ${bits}.`,...(target?[target===1?`I = ${length} · ${bits}.`:`K = ${bits*length}/${bits}.`]:[])],{kind:'alphabet-volume',bits,alphabet,length,target})};
 models.configCost=(l,v)=>{const prices=[rnd(20,50)*1000,rnd(8,15)*1000,rnd(1,5)*1000],quantity=l===1?1:2,budget=rnd(80,120)*1000,total=prices[0]+prices[1]+prices[2]*quantity;return number(`Условные цены: системный блок ${prices[0]} тг, монитор ${prices[1]} тг, один комплект периферии ${prices[2]} тг. Покупают один системный блок, один монитор и ${quantity} ${quantity===1?'комплект':'комплекта'} периферии. ${l===3?`Бюджет ${budget} тг. Сколько останется? При нехватке ответ отрицательный.`:'Какова общая стоимость?'}`,l===3?budget-total:total,'тг','Сначала учтите количество каждого компонента. Остаток бюджета — бюджет минус общая стоимость. Данные условные.','Стоимость = сумма (цена · количество)',[`${prices[0]} + ${prices[1]} + ${prices[2]} · ${quantity} = ${total} тг.`,...(l===3?[`${budget} − ${total}.`]:[])],{kind:'configuration-cost',prices,quantity,budget,l})};
